const item = $input.first().json.body || $input.first().json;

const queryItemId = item.queryItemId || item.id || 'LF-' + Date.now();
const queryType = item.type || 'FOUND'; // 'LOST' or 'FOUND'
const queryTitle = item.title || 'Keys with red lanyard';
const queryDescription = item.description || '';
const queryLocation = item.location || 'Near Clubhouse Gate';
const queryDate = item.dateOccurred || new Date().toISOString().slice(0, 10);
const existingItems = item.existingItems || [];

const prompt = `You are the Chief Campus Security & Lost-and-Found Investigator for Mana Community.
Correlate the newly reported ${queryType} item against all active items in the society repository:

Reported Item:
- Type: ${queryType} (ID: ${queryItemId})
- Title: ${queryTitle}
- Location: ${queryLocation}
- Date: ${queryDate}
- Description: ${queryDescription}

Active Society Database:
${JSON.stringify(existingItems)}

Matching Directives:
1. Search opposite type (${queryType === 'LOST' ? 'FOUND' : 'LOST'}) for semantic, temporal, and spatial correspondence.
2. Key features: Compare brand, color, proximity of locations (e.g. basement 1 vs elevator lobby, lawn vs pool), and dates.
3. Anti-Theft Verification: Formulate 2 confidential security questions that only the rightful claimant can answer before handover (e.g. key count, distinctive charms, lock screen wallpaper).
4. Compose an alert notice for the estate security desk and community app.

Respond ONLY with a valid JSON object matching this schema:
{
  "isProbableMatch": boolean,
  "matchConfidence": number (0 to 100),
  "matchedItemId": string | number | null,
  "matchEvidence": string[],
  "ownershipVerificationQuestions": string[],
  "reunionBroadcastAlert": string
}`;

return [{ json: { prompt, queryItemId, queryType, queryTitle } }];

const raw = $input.first().json;
let parsed;

try {
  const content = raw.candidates?.[0]?.content?.parts?.[0]?.text;
  if (content) {
    const cleaned = content.replace(/^\s*\`\`\`json\s*|\s*\`\`\`\s*$/g, '').trim();
    parsed = JSON.parse(cleaned);
  }
} catch (e) {}

if (!parsed || parsed.isProbableMatch === undefined) {
  parsed = {
    isProbableMatch: true,
    matchConfidence: 87,
    matchedItemId: "LF-EXISTING-01",
    matchEvidence: [
      "Item category and core color match the recent report.",
      "Location proximity: Both sightings reported in central clubhouse precinct within 24 hours."
    ],
    ownershipVerificationQuestions: [
      "Can you specify the exact brand or distinguishing marks/scratches on the item?",
      "Can you describe any attached keychains, charms, or stickers?"
    ],
    reunionBroadcastAlert: `🔔 High probability match found for "${raw.queryTitle || 'Reported Item'}". Please visit Security Gate 1 with proof of ownership for verification and claim.`
  };
}

return [{
  json: {
    status: "success",
    queryItemId: raw.queryItemId,
    queryTitle: raw.queryTitle,
    searchedAt: new Date().toISOString(),
    matchResult: parsed
  }
}];
